/* Timetables for JIIT-128 and JIIT-62, Odd Semester 2026.
 * this page has custom comments made by me so you can easily get the code base
 * the long strings below are a compact encoding of the official
 * grids, chosen because the expanded JSON is roughly seven times larger and this
 * app is meant to open instantly on campus wifi. Edit the source grids and re-run
 * the parser which is always better than editing here by hand.
 *
 * The encoding is documented and is there in docs/DATA_FORMAT.md.
 */

function parseRecords(text)
{
  const rows = text.split(";").map(row =>
  {
    const parts = row.split("|");
    return [parts[0], parts.slice(1)];
  });

  return Object.fromEntries(rows);
}

function splitList(text)
{
  return text.split(";");
}

